{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table prd_db.justherbs.dwh_affiliate_validation as select m.*, coalesce(m.order_date1, n.date) order_date, coalesce(m.final_utm_campaign1, n.campaign_name) final_utm_campaign , coalesce(m.affiliate1, n.affiliate) affiliate, coalesce(m.affiliate_finance1, n.affiliate) affiliate_finance, div0(n.total_spend, count(*) over (partition by coalesce(m.order_date1, n.date),coalesce(m.final_utm_campaign1, n.campaign_name))) total_spend, div0(n.num_engagements,count(*) over (partition by coalesce(m.order_date1, n.date),coalesce(m.final_utm_campaign1, n.campaign_name))) num_engagements, div0(n.num_engagement_users, count(*) over (partition by coalesce(m.order_date1, n.date),coalesce(m.final_utm_campaign1, n.campaign_name))) num_engagement_users, div0(n.num_distributions, count(*) over (partition by coalesce(m.order_date1, n.date),coalesce(m.final_utm_campaign1, n.campaign_name))) num_distributions, div0(n.num_impression_users, count(*) over (partition by coalesce(m.order_date1, n.date),coalesce(m.final_utm_campaign1, n.campaign_name))) num_impression_users, div0(n.num_impressions, count(*) over (partition by coalesce(m.order_date1, n.date),coalesce(m.final_utm_campaign1, n.campaign_name))) num_impressions from ( select order_name , order_timestamp::Date order_Date1 , final_affiliate affiliate1 , trackier_affiliate , affiliate_finance affiliate_finance1 , coalesce(c.shipping_status, b.current_Status) current_Status , a.final_utm_channel , a.final_utm_campaign final_utm_campaign1 , a.discount_code , avg(trackier_payout) payout , sum(total_sales) total_sales , sum(case when lower(coalesce(c.shipping_status,b.current_status, a.order_status)) = \'cancelled\' then total_sales end) cancelled_sales , sum(case when lower(coalesce(c.shipping_status,b.current_status, a.order_status)) <> \'cancelled\' and lower(tags) like \'%return%\' then total_sales end) returned_sales , sum(total_sales) - ifnull(sum(case when lower(coalesce(c.shipping_status,b.current_status, a.order_status)) = \'cancelled\' then total_sales end),0) - ifnull(sum(case when lower(coalesce(c.shipping_status,b.current_status, a.order_status)) <> \'cancelled\' and lower(tags) like \'%return%\' then total_sales end),0) net_sales from prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS a left join prd_db.justherbs.dwh_CLICKPOST_FACT_ITEMS b on a.awb = b.awb_number left join (select awb, shipping_status from ( select awb, shipping_Status, row_number() over (partition by awb order by 1) rw from prd_db.justherbs.EasyEcom_JH_FACT_ITEMS )where rw = 1) c on a.awb = c.awb where (final_Affiliate is not null) or (affiliate_finance is not null) group by 1,2,3,4,5,6,7,8,9 ) m full outer join (select TO_DATE(date_time, \'DD-MON-YY\') date, \'GOOGLEPAY\' Affiliate,upper(\"Campaign Name\") campaign_name, replace(total_spend,\',\',\'\') total_spend, replace(num_engagements,\',\',\'\') num_engagements , replace(num_engagement_users,\',\',\'\') num_engagement_users, replace(num_distributions,\',\',\'\') num_distributions, replace(num_impression_users,\',\',\'\') num_impression_users, replace(num_impressions,\',\',\'\') num_impressions from datalake_db.justherbs.trn_google_pay_campaign_tracker) n on m.order_Date1 = n.date and lower(m.final_utm_campaign1) = lower(n.campaign_name) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from PRD_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            